                    bound = e + K
                    if bound < hi:
                        hi = bound
                    if hi >= lr:
                        cnt += br(arr, hi) - bl(arr, lr)
                key = ai - e - K
                arr = list2.get(key)
                if arr is not None:
                    hi = rr
                    bound = e + K - 1
                    if bound < hi:
                        hi = bound
                    if hi >= lr:
                        cnt += br(arr, hi) - bl(arr, lr)
            parent[left] = right
            sz[right] += sz[left]
            comp[right].extend(comp[left])
            comp[left].clear()
            l[right] = l[left]
        else:
            ll = l[left]
            rl = r[left]
            for e in comp[right]:
                aj = A[e]
                key = aj + e - K
                arr = list1.get(key)
                if arr is not None:
                    lo = ll
                    bound = e - K
                    if bound > lo:
                        lo = bound
                    if lo <= rl:
                        cnt += br(arr, rl) - bl(arr, lo)
                key = aj - e + K
                arr = list2.get(key)
                if arr is not None:
                    lo = ll
                    bound = e - K + 1
                    if bound > lo:
                        lo = bound
                    if lo <= rl:
                        cnt += br(arr, rl) - bl(arr, lo)
            parent[right] = left
            sz[left] += sz[right]
            comp[left].extend(comp[right])
            comp[right].clear()
            r[left] = r[right]
        return cnt

    total = 0
    for i in range(1, N + 1):
        if alive[i]:
            add_vertex(i)
            if i > 1 and alive[i - 1]:
                total += union(find(i - 1), find(i))

    ans = [0] * (Q + 1)
    ans[Q] = total

    for t in range(Q, 0, -1):
        x = D[t]
        add_vertex(x)
        alive[x] = True
        if x > 1 and alive[x - 1]:
            total += union(find(x - 1), find(x))
        if x < N and alive[x + 1]:
            total += union(find(x), find(x + 1))
        ans[t - 1] = total

    sys.stdout.write('\n'.join(map(str, ans)))

if __name__ == "__main__":
    solve()
